package com.adib.maintenance;
import android.content.*;import android.widget.*;import android.view.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.lang.reflect.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={24,28,35}) public class SimpleCardsTest{
@Before public void clear(){RuntimeEnvironment.getApplication().getSharedPreferences("adib-card-style",0).edit().clear().commit();}
@Test public void completedSectionCanCollapseWithoutRemovingTasks()throws Exception{Context c=RuntimeEnvironment.getApplication();LinearLayout host=new LinearLayout(c);CompactDesign.Groups groups=new CompactDesign.Groups(host,false);JSONObject t=new JSONObject().put("completed",true);TextView row=new TextView(c);int[] opened={0};row.setOnClickListener(v->opened[0]++);groups.add(t,row,true);groups.finish();LinearLayout box=(LinearLayout)host.getChildAt(0);box.getChildAt(0).performClick();assertEquals(View.GONE,row.getVisibility());box.getChildAt(0).performClick();assertEquals(View.VISIBLE,row.getVisibility());row.performClick();assertEquals(1,opened[0]);assertEquals(2,box.getChildCount());}
@Test public void datesAreOptionalReadableAndDoNotAlterTask()throws Exception{JSONObject t=new JSONObject();assertEquals("",CompactDesign.date(t));t.put("date","2026-10-12T09:30:00+04:00").put("dateEnd","2026-10-12T10:30:00+04:00");String old=t.toString(),label=CompactDesign.date(t);assertFalse(label.contains("T09"));assertTrue(label.contains("09:30"));assertTrue(label.contains("10:30"));assertEquals(old,t.toString());}
@Test public void neutralCheckboxHas44DpLayoutAndKeepsHandler(){Context c=RuntimeEnvironment.getApplication();Button b=CompactDesign.check(c,true,false);assertNotNull(b.getForeground());int[] count={0};b.setOnClickListener(v->count[0]++);b.performClick();assertEquals(1,count[0]);assertTrue(b.getContentDescription().toString().contains("qaytar"));}
void set(Object a,String n,Object v)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);f.set(a,v);}Object get(Object a,String n)throws Exception{Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(a);}void call(Object a,String n)throws Exception{Method m=a.getClass().getDeclaredMethod(n);m.setAccessible(true);m.invoke(a);}
@Test public void idleHomeCardHasNoRollupOrContainerClutter()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).get();set(a,"screen","home");set(a,"personalTasks",new JSONArray().put(new JSONObject().put("id","a").put("title","EV3 80li1 klapan su buraxır")));call(a,"render");View root=(View)get(a,"root"),row=root.findViewWithTag("home-task:a");assertNotNull(row);View timer=row.findViewWithTag("task-pomodoro:a");assertEquals(View.GONE,timer.getVisibility());assertNotNull(row.findViewWithTag("simple-task-check"));}
}
